  });
  const medX = barX + barW*(median/maxVal);
  slide.addShape(shapes.line, { x: medX, y: y-0.02, w: 0, h, line: { color: color, width: 1, dash: 'dash' } });
  slide.addText(medianLabel, { x: medX-0.43, y: y+h+0.08, w: 0.86, h: 0.14, fontFace:FONT_B, fontSize:6.3, bold:true, color, align:'center', margin:0, fit:'shrink' });
