function drawBarGroup(slide, x, y, w, h, data, color, median, medianLabel, maxVal=90) {
  const labelW = 0.82, valW = 0.35;
  const barX = x + labelW, barW = w - labelW - valW - 0.08;
  const rowH = h / data.length;
  data.forEach((d, i) => {
    const yy = y + i*rowH + 0.035;
    slide.addText(d.name, { x, y: yy+0.015, w: labelW-0.05, h: 0.1, fontFace: FONT_B, fontSize: 6.6, color: C.ink, margin:0, fit:'shrink' });
    slide.addShape(shapes.rect, { x: barX, y: yy+0.04, w: barW, h: 0.1, fill:{color:'E6DFD2'}, line:{color:'E6DFD2'} });
    slide.addShape(shapes.rect, { x: barX, y: yy+0.04, w: barW*(d.val/maxVal), h: 0.1, fill:{color}, line:{color} });
    slide.addText(`${d.val}%`, { x: barX+barW+0.06, y: yy+0.005, w: valW, h: 0.1, fontFace:FONT_B, fontSize:6.6, bold:true, color:C.ink, margin:0 });
  });
  const medX = barX + barW*(median/maxVal);
  slide.addShape(shapes.line, { x: medX, y: y-0.02, w: 0, h, line: { color: color, width: 1, dash: 'dash' } });
  slide.addText(medianLabel, { x: medX-0.43, y: y+h+0.08, w: 0.86, h: 0.14, fontFace:FONT_B, fontSize:6.3, bold:true, color, align:'center', margin:0, fit:'shrink' });
}

